Repair the following GNU C++11 code so that it correctly solves the programming problem. The code reads and writes I/O from the console. Your repaired code should implement the problem correctly, meaning that it should produce the correct output for any valid input.
Print your repaired code and also the confidence score you give to your repair. The confidence score should be a number between 0 and 1. The format of the output should be:
<repaired_code>
<your_repaired_code>
</repaired_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the problem description:
<problem_description>
Alice and Bob are playing a game with a string of characters, with Alice going first. The string consists n characters, each of which is one of the first k letters of the alphabet. On a player’s turn, they can either arbitrarily permute the characters in the words, or delete exactly one character in the word (if there is at least one character). In addition, their resulting word cannot have appeared before throughout the entire game. The player unable to make a valid move loses the game.Given n, k, p, find the number of words with exactly n characters consisting of the first k letters of the alphabet such that Alice will win if both Alice and Bob play optimally. Return this number modulo the prime number p.
</problem_description>

Here is the GNU C++11 code you have to repair:
<original_code>
#include <iostream>
#include <vector>
#include <cmath>
using namespace std;

int main() {
    int n, k, mod;
    cin >> n >> k >> mod;

    vector<int> highestPower(n + 1, 0);
    vector<int> factorial(n + 1, 1);
    vector<int> invFactorial(n + 1, 1);
    vector<vector<int>> dp(27, vector<int>(n + 1, 0));

    invFactorial[0] = invFactorial[1] = factorial[0] = 1;

    for (int i = 2; i <= n; ++i) {
        invFactorial[i] = 1LL * (mod - mod / i) * invFactorial[mod % i] % mod;
    }

    for (int i = 1; i <= n; i <<= 1) {
        for (int j = i >> 1; j < i && j <= n; ++j) {
            highestPower[j] = i;
        }
    }

    for (int i = 1; i <= n; ++i) {
        factorial[i] = 1LL * factorial[i-1] * i % mod;
        invFactorial[i] = 1LL * invFactorial[i-1] * invFactorial[i] % mod;
    }

    int ans = 1;
    int base = k % mod;
    int exp = n;
    while (exp > 0) {
        if (exp & 1) ans = (1LL * ans * base) % mod;
        base = (1LL * base * base) % mod;
        exp >>= 1;
    }

    if (n % 2 == 0) {
        dp[0][0] = 1;
        for (int i = 0; i < 26; ++i) {
            for (int j = 0; j <= n; ++j) {
                if (dp[i][j] && (j & n) == j) {
                    for (int next = j + highestPower[j]; next <= n; next = (next + 1) | j) {
                        if ((next & n) == next) {
                            dp[i+1][next] = (dp[i+1][next] + 1LL * dp[i][j] * invFactorial[next - j] % mod) % mod;
                        }
                    }
                }
            }
        }

        int temp = 0;
        for (int i = 1; i <= 26; ++i) {
            temp = (temp + 1LL * dp[i][n] * invFactorial[k - i] % mod) % mod;
        }
        ans = (ans - 1LL * temp * factorial[n] % mod * factorial[k] % mod + mod) % mod;
    }

    cout << ans << endl;
    return 0;
}
</original_code>
